/// <summary>
/// Extension class of form data source METSalesTable in form SalesCreateOrder
/// </summary>
[ExtensionOf(formDataSourceStr(SalesCreateOrder, SalesTable))]
public final class METSalesCreateOrderFormSalesTableDS_Extension
{
}

Method.Source:
    /// <summary>
    /// Write the record
    /// </summary>
    void write()
    {
        FormDataSource metSalesTable_ds;
        METSalesTable metSalesTableLoc;
        SalesTable salesTableLoc;
        
        next write();
        metSalesTable_ds = this.formRun().dataSource(formDataSourceStr(SalesCreateOrder, METSalesTable));

        if (metSalesTable_ds)
        {
            salesTableLoc = this.cursor();
            metSalesTableLoc = metSalesTable_ds.cursor();
            salesTableLoc.metPackMETSalesTable(metSalesTableLoc);
            //insert in correct order Parent, then extension
            metSalesTableLoc.SysExtensionSerializerExtensionMap::insertAfterBaseTable(salesTableLoc);
        }
    }
